#include<bits/stdc++.h>
#define TAT return 0
using namespace std;
int c,t,n,d,tot=0,sum=0;
int a[1000010];
void bfs(int p,int q,int l)
{
	l++;
	cout<<p<<" "<<q<<" "<<endl;
	for(int i=1;i<=d;i++)//走几步
	{
		int a1=p+i;//走几步后的位置
		if(a1>q)	return ;
		if(a1==q){//在目标岛上
			sum++;
			cout<<endl<<a1<<" "<<q<<" "<<sum<<endl<<endl;
			return;
		}
		for(int j=1;j<=n;j++)//是否在非目标岛上
		{
			if(a1==a[j])
			{
				bfs(a1,q,l);//在非目标岛上，目标不变，向下搜索
				return;
			}
		}
	}
	return ;
}
int main()
{
	//跳岛战术？ 
	//沃补会 
	freopen("migrate.in","r",stdin);
	freopen("migrate.out","w",stdout);
	cin>>c>>t;
	for(int x=1;x<=t;x++)
	{
		
		tot=0;
		cin>>n>>d;
		for(int y=1;y<=n+5;y++)	a[y]=0;
		for(int i=1;i<=n;i++)	cin>>a[i];
		for(int i=2;i<=n;i++)//到第几个岛
		{
			sum=0;
			for(int j=1;j<i;j++)//从第几个岛
			{
				if(a[i]-a[i-1]>d)	break;
				bfs(a[j],a[i],0);//从j到i
			}
			if(sum==2)
				tot++;
		}
		cout<<tot<<endl;
	}
	TAT;
}
